"""Universal detail sheets: (title, group, kind, look, ar, moods, desc, tip, also, terms)
kind: 'sheet' (separate elements on white) | 'overlay' (full-bleed marks on white, use with Multiply)
look: 'i' (ink, detail 10) | 'g' (clean graphic, detail 8)
"""

LS, WD, PL, GF, HW, EN = ("Light and Sparkle", "Wear and Damage", "Paint and Liquid", "Graphic Fillers",
                          "Hardware and Labels", "Energy and Motion")


def D(title, group, kind, look, ar, moods, desc, tip, also, terms):
    return dict(title=title, group=group, kind=kind, look=look, ar=ar, moods=moods, desc=desc, tip=tip, also=also, terms=terms)


